// src/pages/Projects.js
import React from 'react';
import { useTranslation } from 'react-i18next';
import ProjectCard from '../components/ProjectCard';

const Projects = () => {
  const { t } = useTranslation();

  const projects = t('projects.items', { returnObjects: true });
  const metrics = t('projects.metrics', { returnObjects: true });
  const publications = t('projects.pubItems', { returnObjects: true });

  return (
    <main className="page-shell">
      <header className="page-header">
        <span className="eyebrow">{t('projects.eyebrow')}</span>
        <h1 className="page-title">{t('projects.title')}</h1>
        <p className="page-lead">{t('projects.lead')}</p>
      </header>

      <section className="metric-grid">
        {metrics.map((metric) => (
          <article className="metric-card panel panel--pad" key={metric.label}>
            <strong>{metric.value}</strong>
            <span>{metric.label}</span>
          </article>
        ))}
      </section>

      <section className="section-block">
        <div className="card-grid">
          {projects.map((project) => (
            <ProjectCard key={project.id} {...project} />
          ))}
        </div>
      </section>

      <section className="section-block">
        <div className="section-heading">
          <div>
            <span className="eyebrow">{t('projects.pubEyebrow')}</span>
            <h2 className="section-title">{t('projects.pubTitle')}</h2>
          </div>
        </div>

        <div className="panel panel--pad">
          <ol className="publication-list">
            {publications.map((item) => (
              <li key={item}>{item}</li>
            ))}
          </ol>
        </div>
      </section>
    </main>
  );
};

export default Projects;

